mapper.select:
select  * from (
select lips.id, lips.product_date, lips.lh_machine_code, lips.lh_stream_code, lips.sap_code,
lips.left_right_mold, lips.is_empty_mold, lips.create_by, lips.create_time, lips.update_by, lips.update_time, lips.del_flag, lips.remark,
lmi.machine_name
from t_lh_in_production_spec lips
left join T_LH_MACHINE_INFO lmi
on lips.lh_machine_code = lmi.machine_code and lmi.del_flag = 0
where lips.del_flag = '0'
and lips.product_date = #{productDate}
and lips.lh_machine_code = #{lhMachineCode}
and lips.lh_stream_code = #{lhStreamCode}
and lips.sap_code = #{sapCode}
and lips.left_right_mold = #{leftRightMold}
and lips.is_empty_mold = #{isEmptyMold}
) t
order by create_time desc
order by ${orderStr}

mapper.update:
update t_lh_in_production_spec
product_date = #{productDate}, lh_machine_code = #{lhMachineCode}, lh_stream_code = #{lhStreamCode}, sap_code = #{sapCode}, left_right_mold = #{leftRightMold}, is_empty_mold = #{isEmptyMold}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime}, del_flag = #{delFlag}, remark = #{remark},
where id = #{id}

mapper.delete:
update t_lh_in_production_spec
set del_flag='1'
where id = #{id}
